import React from "react";
import './grid.css';
import Row from "./row";

interface GridProps {
    word: string;
    guessNumber: number;
}

const Grid: React.FC<GridProps> = ({word, guessNumber}) => {
    return(
        <>
            <div className="gridcontainer">
                <Row word = {word}/>
                <Row word = {word}/>
                <Row word = {word}/>
                <Row word = {word}/>
                <Row word = {word}/>
                <Row word = {word}/>
            </div>
        </>
    );
}

export default Grid;
